/* SODRE 2026 - NOVO HEADER MOBILE */
(function() {
    if (window.__S26MOBILEV3) return;
    window.__S26MOBILEV3 = 1;
    var CSS = '@media(max-width:979px){body.s26m-open{overflow:hidden!important}.atalhos-mobile{display:none!important}.s26m{display:block!important;background:#fff!important;position:relative!important;z-index:99990!important;font-family:Poppins,Arial,sans-serif!important}.s26m-top{height:42px!important;padding:0 14px!important;display:flex!important;align-items:center!important;justify-content:space-between!important;gap:8px!important;background:linear-gradient(100deg,#3d209c,#9d147d 52%,#f80446)!important;color:#fff!important}.s26m-slogan{white-space:nowrap!important;font-size:0!important;font-weight:900!important;font-style:italic!important;line-height:1!important}.s26m-slogan strong{display:block!important;color:#fff!important;font-size:11px!important;line-height:11px!important}.s26m-slogan small{display:block!important;color:#fff!important;font-size:6px!important;line-height:8px!important;text-align:center!important}.s26m-toplinks{display:flex!important;align-items:center!important;justify-content:flex-end!important;gap:13px!important;white-space:nowrap!important}.s26m-toplinks a{color:#fff!important;text-decoration:none!important;font-size:6.5px!important;font-weight:800!important;line-height:1!important}.s26m-main{position:relative!important;height:62px!important;display:flex!important;align-items:center!important;justify-content:center!important;border-bottom:1px solid #f80446!important;background:#fff!important}.s26m-menu{position:absolute!important;left:20px!important;top:50%!important;transform:translateY(-50%)!important;width:27px!important;height:32px!important;padding:0!important;margin:0!important;border:0!important;background:transparent!important;display:flex!important;flex-direction:column!important;justify-content:center!important;gap:5px!important;cursor:pointer!important}.s26m-menu span{display:block!important;width:21px!important;height:2px!important;border-radius:2px!important;background:#f80446!important}.s26m-logo{display:flex!important;align-items:center!important;justify-content:center!important;width:125px!important;height:50px!important}.s26m-logo img{display:block!important;width:auto!important;max-width:125px!important;max-height:46px!important;height:auto!important;object-fit:contain!important}.s26m-actions{position:absolute!important;right:16px!important;top:50%!important;transform:translateY(-50%)!important;display:flex!important;align-items:center!important;gap:6px!important}.s26m-action{width:30px!important;height:30px!important;display:flex!important;align-items:center!important;justify-content:center!important;border-radius:50%!important;background:linear-gradient(135deg,#4420a6,#f80446)!important;color:#fff!important;text-decoration:none!important;font-size:14px!important;box-sizing:border-box!important}.s26m-action i{color:#fff!important;margin:0!important;font-size:14px!important}.s26m-searchrow{height:52px!important;padding:9px 20px 10px!important;background:#fff!important;box-sizing:border-box!important}.s26m-search{position:relative!important;width:100%!important;height:33px!important;margin:0!important;border-radius:999px!important;background:#eee!important;overflow:hidden!important}.s26m-search input{display:block!important;width:100%!important;height:33px!important;min-height:33px!important;margin:0!important;padding:0 43px 0 14px!important;border:0!important;outline:0!important;border-radius:999px!important;background:#eee!important;color:#777!important;font:400 10px/33px Poppins,Arial,sans-serif!important;box-sizing:border-box!important;box-shadow:none!important}.s26m-search button{position:absolute!important;right:2px!important;top:2px!important;width:29px!important;height:29px!important;min-width:29px!important;min-height:29px!important;margin:0!important;padding:0!important;border:0!important;border-radius:50%!important;background:#f80446!important;color:#fff!important;display:flex!important;align-items:center!important;justify-content:center!important}.s26m-search button i{color:#fff!important;font-size:13px!important;margin:0!important}.s26m-overlay{position:fixed!important;inset:0!important;z-index:2147483600!important;background:rgba(12,8,52,.58)!important;opacity:0!important;visibility:hidden!important;pointer-events:none!important;transition:opacity .25s ease,visibility .25s ease!important}.s26m-drawer{position:fixed!important;left:0!important;top:0!important;bottom:0!important;width:82vw!important;max-width:320px!important;height:100dvh!important;z-index:2147483601!important;background:#fff!important;box-shadow:15px 0 40px rgba(0,0,0,.2)!important;transform:translateX(-105%)!important;transition:transform .28s ease!important;overflow-y:auto!important;overscroll-behavior:contain!important}.s26m-open .s26m-overlay{opacity:1!important;visibility:visible!important;pointer-events:auto!important}.s26m-open .s26m-drawer{transform:translateX(0)!important}.s26m-drawerhead{height:78px!important;padding:0 17px!important;display:flex!important;align-items:center!important;justify-content:space-between!important;background:linear-gradient(105deg,#3d209c,#9d147d 50%,#f80446)!important;box-sizing:border-box!important}.s26m-drawerbrand strong{display:block!important;color:#fff!important;font:900 italic 14px/15px Poppins,Arial,sans-serif!important}.s26m-drawerbrand small{display:block!important;color:#fff!important;font:600 9px/12px Poppins,Arial,sans-serif!important}.s26m-close{width:34px!important;height:34px!important;padding:0!important;border:1px solid rgba(255,255,255,.85)!important;border-radius:50%!important;background:transparent!important;color:#fff!important;font:300 25px/30px Arial,sans-serif!important}.s26m-nav{padding:13px 18px 30px!important}.s26m-nav a{display:flex!important;align-items:center!important;width:100%!important;min-height:49px!important;padding:9px 4px!important;box-sizing:border-box!important;border-bottom:1px solid #e8e7ed!important;background:#fff!important;color:#211267!important;font:800 12px/1.25 Poppins,Arial,sans-serif!important;text-decoration:none!important;text-transform:uppercase!important}.s26m-sep{height:1px!important;margin:14px 0!important;background:#c9c7d1!important}.s26m-nav a.s26m-extra{color:#d40846!important}body.s26m-open .s26-map-slot,body.s26m-open .container-mapa,body.s26m-open #card_pesquisa,body.s26m-open #info_labs{z-index:0!important;pointer-events:none!important}body.s26m-active>#cabecalho,body.s26m-active>.barra-inicial{display:none!important}body.s26m-active #cabecalho{display:none!important}}@media(min-width:980px){.s26m,.s26m-overlay,.s26m-drawer{display:none!important}}';

    function q(s, r) { return (r || document).querySelector(s) }

    function qa(s, r) { return Array.prototype.slice.call((r || document).querySelectorAll(s)) }

    function txt(e) { return (e && e.textContent || "").replace(/\\s+/g, " ").trim() }

    function href(names) {
        var links = qa("a"),
            n = names.toLowerCase();
        for (var i = 0; i < links.length; i++) { if (txt(links[i]).toLowerCase().indexOf(n) > -1 && links[i].href) return links[i].href }
        return "#"
    }

    function icon(el, fallback) { if (!el) return fallback; var i = q("i", el); return i ? i.outerHTML : fallback }

    function close() { document.body.classList.remove("s26m-open") }

    function build() {
        if (window.innerWidth > 979) { close(); return }
        if (q(".s26m")) return;
        var nativeHeader = q("#cabecalho"),
            logo = q("#cabecalho .logo img"),
            cart = q("#cabecalho .carrinho a"),
            account = q("#cabecalho .acoes-conta li:last-child a") || q("#cabecalho .acoes-conta a"),
            search = q("#cabecalho .busca input"),
            form = search && search.closest("form"),
            top = q(".btns-barra-inicial"),
            logoSrc = logo ? logo.src : "";
        var acesso = href("acesso credenciado"),
            portal = href("portal empresa");
        if (top) { qa("a", top).forEach(function(a) { var t = txt(a).toLowerCase(); if (t.indexOf("acesso credenciado") > -1) acesso = a.href; if (t.indexOf("portal empresa") > -1) portal = a.href }) }
        var style = document.createElement("style");
        style.id = "s26m-style";
        style.textContent = CSS;
        document.head.appendChild(style);
        var h = document.createElement("header");
        h.className = "s26m";
        h.innerHTML = '<div class="s26m-top"><div class="s26m-slogan"><strong># 1º DO BRASIL</strong><small>em toxicologia</small></div><div class="s26m-toplinks"><a href="' + acesso + '">ACESSO CREDENCIADO</a><a href="' + portal + '">PORTAL EMPRESA</a></div></div><div class="s26m-main"><button type="button" class="s26m-menu" aria-label="Abrir menu"><span></span><span></span><span></span></button><a class="s26m-logo" href="/">' + (logoSrc ? '<img src="' + logoSrc + '" alt="Sodré Laboratório">' : "SODRÉ") + '</a><div class="s26m-actions"><a class="s26m-action s26m-cart" href="' + (cart ? cart.href : "/carrinho/index") + '" aria-label="Carrinho">' + icon(cart, '<i class="icon-shopping-cart"></i>') + '</a><a class="s26m-action s26m-profile" href="' + (account ? account.href : "/conta/index") + '" aria-label="Minha conta">' + icon(account, '<i class="icon-user"></i>') + '</a></div></div><div class="s26m-searchrow"><form class="s26m-search" action="' + (form ? form.action : "/buscar") + '" method="get"><input type="text" name="' + (search && search.name ? search.name : "q") + '" placeholder="' + (search && search.placeholder ? search.placeholder : "Digite o que você procura") + '"><button type="submit" aria-label="Buscar"><i class="icon-search"></i></button></form></div>';
        var overlay = document.createElement("div");
        overlay.className = "s26m-overlay";
        var drawer = document.createElement("aside");
        drawer.className = "s26m-drawer";
        drawer.innerHTML = '<div class="s26m-drawerhead"><div class="s26m-drawerbrand"><strong># 1º DO BRASIL</strong><small>em toxicologia</small></div><button type="button" class="s26m-close" aria-label="Fechar menu">×</button></div><nav class="s26m-nav"><a href="' + href("seja um credenciado") + '">SEJA UM CREDENCIADO</a><a href="' + href("pontos de coleta") + '">PONTOS DE COLETA</a><a href="' + href("resultado de exame") + '">RESULTADO DE EXAME</a><a href="' + href("como foi atendido") + '">COMO FOI ATENDIDO?</a><div class="s26m-sep"></div><a class="s26m-extra" href="' + acesso + '">ACESSO CREDENCIADO</a><a class="s26m-extra" href="' + portal + '">PORTAL EMPRESA</a></nav>';
        var ref = nativeHeader || document.body.firstChild;
        if (nativeHeader && nativeHeader.parentNode) nativeHeader.parentNode.insertBefore(h, nativeHeader);
        else document.body.insertBefore(h, document.body.firstChild);
        document.body.appendChild(overlay);
        document.body.appendChild(drawer);
        document.body.classList.add("s26m-active");
        q(".s26m-menu", h).addEventListener("click", function(e) {
            e.preventDefault();
            document.body.classList.add("s26m-open")
        });
        q(".s26m-close", drawer).addEventListener("click", close);
        overlay.addEventListener("click", close);
        qa(".s26m-nav a", drawer).forEach(function(a) { a.addEventListener("click", close) })
    }

    function init() { if (window.innerWidth <= 979) build() }
    document.readyState === "loading" ? document.addEventListener("DOMContentLoaded", init) : init();
    setTimeout(init, 300);
    setTimeout(init, 1000);
    document.addEventListener("keydown", function(e) { if (e.key === "Escape") close() });
    window.addEventListener("resize", function() {
        if (window.innerWidth > 979) close();
        else build()
    })
})();


/// cards

/**
 * SODRÉ TOXICOLÓGICO
 * Cards da Home - Mobile
 *
 * Responsabilidade exclusiva:
 * - Ajustar os cards da home no mobile
 * - Não altera header, menu, footer ou outros componentes
 */

(function() {
    'use strict';

    const MOBILE_BREAKPOINT = 979;
    const CARD_SELECTOR =
        '.card-detran, .card-empresas, .card-concurso, .card-carreira';

    let initialized = false;
    let observer = null;
    let resizeTimer = null;

    /**
     * Aplica uma propriedade inline com !important.
     */
    function style(element, properties) {
        if (!element) return;

        Object.keys(properties).forEach(function(property) {
            element.style.setProperty(
                property,
                properties[property],
                'important'
            );
        });
    }

    /**
     * Remove somente os estilos inline criados por este script.
     * Usado quando o usuário volta para o desktop.
     */
    function clearStyles(element, properties) {
        if (!element) return;

        properties.forEach(function(property) {
            element.style.removeProperty(property);
        });
    }

    /**
     * Ajusta um único card.
     */
    function buildCard(card) {

        if (!card) return;

        /* ==============================
           CARD
        ============================== */

        style(card, {
            'position': 'relative',
            'width': '310px',
            'max-width': '310px',
            'min-width': '310px',
            'margin': '0 auto',
            'padding': '0',
            'border': '0',
            'background': 'transparent',
            'box-shadow': 'none',
            'overflow': 'visible',
            'text-align': 'center',
            'box-sizing': 'border-box'
        });


        /* ==============================
           FAIXA SUPERIOR
        ============================== */

        const pill = card.querySelector('.s26-product__pill');

        style(pill, {
            'position': 'relative',
            'z-index': '2',

            'width': '252px',
            'height': '51px',
            'min-height': '51px',

            'margin': '0 auto -26px',
            'padding': '0',

            'display': 'flex',
            'align-items': 'center',
            'justify-content': 'center',

            'border-radius': '999px',

            'background': 'linear-gradient(100deg,#352198 0%,#95166d 52%,#ff003f 100%)',

            'color': '#ffffff',

            'font-family': 'Lexend, Poppins, Arial, sans-serif',
            'font-size': '25px',
            'font-weight': '800',
            'line-height': '1',

            'white-space': 'nowrap'
        });


        /* ==============================
           CORPO CINZA
        ============================== */

        const body = card.querySelector('.s26-product__body');

        style(body, {
            'position': 'relative',

            'width': '100%',
            'min-height': '288px',

            'padding': '56px 28px 20px',

            'border-radius': '18px',

            'background': '#f1f1f2',

            'box-sizing': 'border-box'
        });


        /* ==============================
           NOME DO EXAME
        ============================== */

        const name = card.querySelector('.s26-product__name');

        style(name, {
            'min-height': '48px',

            'margin': '0 0 18px',

            'padding': '0',

            'color': '#454550',

            'font-family': 'Poppins, Arial, sans-serif',
            'font-size': '16px',
            'font-weight': '500',
            'line-height': '1.18',

            'text-align': 'center'
        });


        /* ==============================
           PREÇO
        ============================== */

        const price = card.querySelector('.s26-product__price');

        if (price) {

            style(price, {
                'display': 'inline-grid',

                'grid-template-columns': 'auto auto',
                'grid-template-rows': '16px 42px',

                'align-items': 'end',
                'justify-content': 'center',

                'column-gap': '4px',
                'row-gap': '0',

                'width': 'max-content',

                'margin': '0 auto',

                'padding': '0',

                'color': '#cc123d'
            });


            /* A partir de */

            const prefix =
                price.querySelector('.s26-product__prefix') ||
                price.querySelector(':scope > span');

            style(prefix, {
                'grid-column': '1',
                'grid-row': '1',

                'justify-self': 'end',
                'align-self': 'end',

                'margin': '0 -1px -3px 0',

                'padding': '0',

                'color': '#50505a',

                'font-family': 'Poppins, Arial, sans-serif',
                'font-size': '11px',
                'font-weight': '800',
                'line-height': '1',

                'white-space': 'nowrap'
            });


            /* STRONG */

            const strong = price.querySelector('strong');

            style(strong, {
                'display': 'contents',
                'color': '#cc123d',
                'font-weight': '900'
            });


            /* R$ */

            const currency = price.querySelector('small');

            style(currency, {
                'grid-column': '1',
                'grid-row': '2',

                'justify-self': 'end',
                'align-self': 'start',

                'margin': '5px 0 0',

                'padding': '0',

                'color': '#cc123d',

                'font-family': 'Montserrat, Poppins, Arial, sans-serif',
                'font-size': '21px',
                'font-weight': '900',
                'line-height': '1',

                'white-space': 'nowrap'
            });


            /* 129,90 */

            const amount =
                price.querySelector('.s26-product__amount');

            style(amount, {
                'grid-column': '2',
                'grid-row': '1 / 3',

                'align-self': 'end',

                'display': 'block',

                'margin': '0',
                'padding': '0',

                'color': '#cc123d',

                'font-family': 'Montserrat, Poppins, Arial, sans-serif',
                'font-size': '46px',
                'font-weight': '900',
                'line-height': '.88',

                'letter-spacing': '-1px',

                'white-space': 'nowrap'
            });
        }


        /* ==============================
           PARCELAMENTO
        ============================== */

        const installment = card.querySelector(
            '.s26-product__installment, .s26-product__installments'
        );

        style(installment, {
            'width': '206px',
            'max-width': '100%',
            'min-height': '34px',

            'margin': '7px auto 27px',

            'padding': '0',

            'color': '#62616a',

            'font-family': 'Poppins, Arial, sans-serif',
            'font-size': '13px',
            'font-weight': '400',
            'line-height': '1.12',

            'text-align': 'right'
        });

        if (installment) {
            installment
                .querySelectorAll('strong, b')
                .forEach(function(element) {
                    style(element, {
                        'font-weight': '800',
                        'color': '#4d4b54'
                    });
                });
        }


        /* ==============================
           AÇÕES
        ============================== */

        const actions = card.querySelector('.s26-product__actions');

        style(actions, {
            'display': 'flex',
            'align-items': 'center',
            'justify-content': 'center',

            'width': '100%',

            'margin': '0',
            'padding': '0',

            'gap': '0'
        });


        /* ==============================
           BOTÃO COMPRE AGORA
        ============================== */

        const buy = card.querySelector('.s26-product__buy');

        style(buy, {
            'display': 'inline-flex',
            'align-items': 'center',
            'justify-content': 'center',

            'width': '160px',
            'height': '40px',
            'min-height': '40px',

            'margin': '0',
            'padding': '0 16px',

            'box-sizing': 'border-box',

            'border': '0',
            'border-radius': '999px',

            'background': '#30208f',

            'color': '#ffffff',

            'font-family': 'Lexend, Poppins, Arial, sans-serif',
            'font-size': '14px',
            'font-weight': '800',
            'line-height': '1',

            'text-decoration': 'none',

            'white-space': 'nowrap'
        });


        /* ==============================
           REMOVE "SAIBA MAIS"
        ============================== */

        card
            .querySelectorAll('.s26-product__more')
            .forEach(function(element) {
                style(element, {
                    'display': 'none'
                });
            });


        /* ==============================
           TEXTO ABAIXO DO CARD
        ============================== */

        const note = card.querySelector('.s26-product__note');

        style(note, {
            'margin': '9px 0 0',

            'padding': '0',

            'color': '#77747e',

            'font-family': 'Poppins, Arial, sans-serif',
            'font-size': '13px',
            'font-weight': '400',
            'line-height': '1.1',

            'text-align': 'center'
        });


        card.dataset.s26MobileReady = '1';
    }


    /**
     * Monta todos os cards.
     */
    function buildCards() {

        if (window.innerWidth > MOBILE_BREAKPOINT) {
            return;
        }

        const sections =
            document.querySelectorAll('.cards-sodre.s26-products');

        if (!sections.length) {
            return;
        }

        sections.forEach(function(section) {

            /*
             * Primeiro escondemos.
             * Isso evita mostrar o card antigo durante a montagem.
             */

            style(section, {
                'visibility': 'hidden',
                'opacity': '0'
            });


            /* Container principal */

            style(section, {
                'width': '100%',
                'max-width': '390px',

                'margin': '34px auto',

                'padding': '0 16px',

                'box-sizing': 'border-box',

                'overflow': 'visible'
            });


            /* Grid */

            const container =
                section.querySelector('.container-cards');

            style(container, {
                'display': 'grid',

                'grid-template-columns': '310px',

                'justify-content': 'center',

                'gap': '34px',

                'width': '100%',

                'margin': '0',

                'padding': '0'
            });


            /* Cards */

            section
                .querySelectorAll(CARD_SELECTOR)
                .forEach(buildCard);


            /*
             * Somente depois de tudo pronto,
             * mostramos a seção.
             */

            style(section, {
                'visibility': 'visible',
                'opacity': '1'
            });
        });

        initialized = true;
    }


    /**
     * Aguarda a Loja Integrada criar os cards.
     */
    function waitForCards() {

        if (window.innerWidth > MOBILE_BREAKPOINT) {
            return;
        }

        const cards =
            document.querySelector('.cards-sodre.s26-products');

        if (cards) {
            buildCards();
            return;
        }

        observer = new MutationObserver(function() {

            const cards =
                document.querySelector('.cards-sodre.s26-products');

            if (!cards) return;

            buildCards();

            observer.disconnect();
            observer = null;
        });

        observer.observe(document.body, {
            childList: true,
            subtree: true
        });
    }


    /**
     * Inicialização.
     */
    function init() {

        if (window.innerWidth > MOBILE_BREAKPOINT) {
            return;
        }

        waitForCards();

        /*
         * Segunda passagem.
         * Serve para conteúdo que a Loja Integrada
         * altera alguns milissegundos depois.
         */

        setTimeout(buildCards, 100);
        setTimeout(buildCards, 500);
        setTimeout(buildCards, 1200);
    }


    /**
     * DOM pronto.
     */
    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', init);
    } else {
        init();
    }


    /**
     * Resize / mudança de orientação.
     */
    window.addEventListener('resize', function() {

        clearTimeout(resizeTimer);

        resizeTimer = setTimeout(function() {

            if (window.innerWidth <= MOBILE_BREAKPOINT) {
                buildCards();
            }

        }, 150);
    });

})();